head.script:
scwin.init = function() {
    var jsonData = [{
            "label": "select_gridViewItemset",
            "code": "select_gridViewItemset"
        },
        {
            "label": "autoComplete_gridViewItemset",
            "code": "autoComplete_gridViewItemset"
        },
        {
            "label": "checkcombobox_gridViewItemset",
            "code": "checkcombobox_gridViewItemset"
        },
        {
            "label": "autoComplete",
            "code": "autoComplete"
        },
        {
            "label": "input",
            "code": "input"
        },
        {
            "label": "calendar",
            "code": "calendar"
        },
        {
            "label": "checkbox",
            "code": "checkbox"
        },
        {
            "label": "select",
            "code": "select"
        },
        {
            "label": "radio",
            "code": "radio"
        }
    ];
    dlt_select.setJSON(jsonData);
    var sel_sampleData = [{
            "col1": "축구",
            "col2": "1"
        },
        {
            "col1": "농구",
            "col2": "2"
        },
        {
            "col1": "야구",
            "col2": "3"
        },
        {
            "col1": "배구",
            "col2": "4"
        }
    ];
    sel_sample.setJSON(sel_sampleData);
    var arr = [];
    for (var i = 0; i < 5; i++) {
        arr.push(new Array);
    }
    dataList1.setJSON(arr);
    var dl_json = [{
        "label": "라벨1",
        "value": "값1",
        "col3": ""
    }, {
        "label": "라벨2",
        "value": "값2",
        "col3": ""
    }, {
        "label": "라벨3",
        "value": "값3",
        "col3": ""
    }, {
        "label": "라벨4",
        "value": "값4",
        "col3": ""
    }, {
        "label": "라벨5",
        "value": "값5",
        "col3": ""
    }];
    dataList2.setJSON(dl_json);
};
scwin.grd_onviewchange = function(info) {
    var inputType = info.newValue;
    var obj = scwin.inputTypeCustomObj[inputType];
    if (obj) {
        grd.setCellInputType(info.rowIndex, "col2", obj);
    }
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.inputTypeCustomObj = {
        calendar: {
            inputType: "calendar"
        },
        radio: {
            inputType: "radio"
        },
        checkbox: {
            inputType: "checkbox"
        },
        input: {
            inputType: "text"
        },
        select: {
            inputType: "select",
            options: {
                viewType: "default"
            },
            itemSet: {
                nodeset: "data:sel_sample",
                label: "col1",
                value: "col2"
            }
        },
        autoComplete: {
            inputType: "autoComplete",
            options: {
                viewType: "default"
            },
            itemSet: {
                nodeset: "data:sel_sample",
                label: "col1",
                value: "col2"
            }
        },
        select_gridViewItemset: {
            inputType: "select",
            nodeset: "data:dataList2",
            label: "label",
            value: "value",
            item: [{
                    ref: "label",
                    header: "LABEL"
                },
                {
                    ref: "value",
                    header: "VALUE"
                },
                {
                    ref: "col3",
                    header: "COL3"
                }
            ],
            itemTableType: "gridViewItemset",
            width: "330",
            visibleRowNum: "3",
            rowNumVisible: "true",
            hideHeader: "true",
        },
        autoComplete_gridViewItemset: {
            inputType: "autoComplete",
            nodeset: "data:dataList2",
            label: "label",
            value: "value",
            item: [{
                    ref: "label",
                    header: "LABEL"
                },
                {
                    ref: "value",
                    header: "VALUE"
                },
                {
                    ref: "col3",
                    header: "COL3"
                }
            ],
            itemTableType: "gridViewItemset",
            width: "330",
            visibleRowNum: "3",
            rowNumVisible: "true",
            hideHeader: "true",
        },
        checkcombobox_gridViewItemset: {
            inputType: "checkcombobox",
            nodeset: "data:dataList2",
            label: "label",
            value: "value",
            item: [{
                    inputType: "checkbox",
                    ref: "col3",
                    header: "COL3"
                },
                {
                    ref: "label",
                    header: "LABEL"
                },
                {
                    ref: "value",
                    header: "VALUE"
                }
            ],
            itemTableType: "gridViewItemset",
            width: "170",
            visibleRowNum: "3",
            rowNumVisible: "true",
            checkColumn: "0"
        }
    };
    //값 변경 시 col2의 inputType을 동적으로 변경한다.
    scwin.init();
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
